import * as THREE from './three.module.js';
import {createRacketModel} from './racket-model.js';
import {strokePose,armTo} from './arm-pose.js';
export function createArmRig(skin,cloth,wood,bandMaterial=null){const root=new THREE.Group(),bones=[],up=new THREE.Vector3(0,1,0);
 function segment(radius,material){const m=new THREE.Mesh(new THREE.CapsuleGeometry(radius,1-2*radius,6,24),material);m.castShadow=true;root.add(m);return m;}
 const upper=segment(.061,skin),forearm=segment(.050,skin),sleeve=segment(.084,cloth);const elbow=new THREE.Mesh(new THREE.SphereGeometry(.054,24,16),skin),wrist=new THREE.Mesh(new THREE.SphereGeometry(.046,24,16),skin);root.add(elbow,wrist);
 const sweatband=bandMaterial?segment(.055,bandMaterial):null;if(sweatband)sweatband.userData.wristband=true;
 const racket=new THREE.Group();root.add(racket);const palm=new THREE.Mesh(new THREE.SphereGeometry(.047,24,16),skin);palm.scale.set(1.05,.70,.65);palm.position.set(-.055,0,.005);racket.add(palm);const thumb=new THREE.Mesh(new THREE.SphereGeometry(.022,20,12),skin);thumb.scale.set(1.4,.7,.75);thumb.position.set(-.035,-.027,.014);racket.add(thumb);racket.add(createRacketModel());
 function fit(mesh,a,b){const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),d=B.clone().sub(A);mesh.position.copy(A).add(B).multiplyScalar(.5);mesh.scale.y=d.length();mesh.quaternion.setFromUnitVectors(up,d.normalize());}
 function pose(position,hand,kind='regular',ready=0){let p=strokePose(position,hand);const blend=Math.max(0,Math.min(1,ready)),quaternion=new THREE.Quaternion().setFromEuler(new THREE.Euler(kind==='lob'?.65:0,p.yaw,0));if(blend>0){const desired=p.wrist.map((v,i)=>v+([-.035,.89,.38][i]-v)*blend);const pole=p.elbow.map((v,i)=>(v-p.shoulder[i])*(1-blend)+[-.6,-.2,0][i]*blend);p={...p,...armTo(p.shoulder,desired,pole)};const readyRotation=new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(-1,0,0),new THREE.Vector3(.035,.43,.08).normalize());readyRotation.multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(-1,0,0),Math.PI/2));quaternion.slerp(readyRotation,blend);p.shaft=new THREE.Vector3(-1,0,0).applyQuaternion(quaternion).toArray();p.head=p.wrist.map((v,i)=>v+p.shaft[i]*.45);}fit(upper,p.shoulder.map((v,i)=>v+(p.elbow[i]-v)*.47),p.elbow);fit(forearm,p.elbow,p.wrist);const cuff=p.shoulder.map((v,i)=>v+(p.elbow[i]-v)*.52);fit(sleeve,p.shoulder,cuff);elbow.position.set(...p.elbow);wrist.position.set(...p.wrist);if(sweatband)fit(sweatband,p.elbow.map((v,i)=>v+(p.wrist[i]-v)*.78),p.elbow.map((v,i)=>v+(p.wrist[i]-v)*.96));racket.position.set(...p.wrist);racket.quaternion.copy(quaternion);racket.scale.x=1;return p;}
 function poseService(p,shaft){fit(upper,p.shoulder.map((v,i)=>v+(p.elbow[i]-v)*.47),p.elbow);fit(forearm,p.elbow,p.wrist);fit(sleeve,p.shoulder,p.shoulder.map((v,i)=>v+(p.elbow[i]-v)*.52));elbow.position.set(...p.elbow);wrist.position.set(...p.wrist);if(sweatband)fit(sweatband,p.elbow.map((v,i)=>v+(p.wrist[i]-v)*.78),p.elbow.map((v,i)=>v+(p.wrist[i]-v)*.96));racket.position.set(...p.wrist);racket.quaternion.setFromUnitVectors(new THREE.Vector3(-1,0,0),new THREE.Vector3(...shaft));return {head:p.wrist.map((v,i)=>v+shaft[i]*.45)};}
 pose(0,1);return {root,pose,poseService};}
